            ActoadminEtapaPeer::addSelectColumns($criteria);
        }

        $criteria->clearOrderByColumns(); // ORDER BY won't ever affect the count

        // Set the correct dbName
        $criteria->setDbName(ActoadminEtapaPeer::DATABASE_NAME);

        if ($con === null) {
            $con = Propel::getConnection(ActoadminEtapaPeer::DATABASE_NAME, Propel::CONNECTION_READ);
